    out[U_HUE_SHIFT4] = fract4(ctx.bars / Math.max(num5(p, "hueBars", 1e-3, 4096), 1e-3)) * TAU4;
    out[U_SCALE4] = num5(p, "fit", 0, 1) * Math.min(1, ctx.aspect * 1.15);
